  "groups": [
    {
      "all_of": [
        {
          "condition": "holds Premier Preferred Vendor status",
          "item": "e_007598"
        }
      ]
    },
    {
      "all_of": [
        {
          "condition": "employs ≥ 40 software engineers",
          "item": "e_00b939"
        },
        {
          "condition": "annual turnover ≥ 10,000,000 USD",
          "item": "e_00b6a4"
        },
        {
